// Find the booking being moved, and decide whether this requester may move it.
// Same shape as Cancel Booking: the calendar is read and the id is checked
// against it, because the model has invented one before. The title it showed
// the requester resolves the booking too, so no id is needed at all.
const REQ = $('When Executed by Another Workflow').first().json;
const raw = $input.first().json || {};
const me = String(REQ.requester || '').trim();
const confirmed = REQ.confirmed === true || String(REQ.confirmed).toLowerCase() === 'true';
const wantedId = String(REQ.event_id || '').trim();
const wantedTitle = String(REQ.title || '').trim();
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const when = e => {
  const s = (e.start && e.start.dateTime) || '';
  if (!s) return '(all day)';
  return '(' + new Date(s).toLocaleTimeString('en-US', { timeZone:'Asia/Manila', hour:'numeric', minute:'2-digit' }) + ')';
};
const bad = (reason, human) => [{ json: { verdict:'REJECTED', reason, human } }];

if (!confirmed) return bad('NOT_CONFIRMED',
  'Nothing was moved. Show the requester the booking and the new time, end that message with the line '
  + '"Confirm to move. (y/n)", and stop. Move it only after they reply y.');
if (!String(REQ.booking_date || '').trim()) return bad('MISSING_DATE',
  'Nothing was moved - no booking date was given. Call Move Booking again with the date the booking is on now.');
if (!wantedId && !wantedTitle) return bad('MISSING_DETAILS',
  'Nothing was moved - no booking title was given. Call Move Booking again with the title exactly as you showed it.');
const ns = new Date(String(REQ.new_start_iso || '')).getTime();
const ne = new Date(String(REQ.new_end_iso || '')).getTime();
if (!ns || !ne) return bad('MISSING_TIMES',
  'Nothing was moved - the new start and end times were missing or unreadable. Ask the requester for the new time and try again.');
if (ne <= ns) return bad('DURATION_INVALID',
  'Nothing was moved - the new end time is not after the new start time. Check the times with the requester.');

const items = Array.isArray(raw.items) ? raw.items.filter(e => e.status !== 'cancelled') : null;
if (!items) return bad('LOOKUP_FAILED',
  'Nothing was moved - the calendar could not be read for that date. Tell the requester it did not go through.');

let ev = wantedId ? items.find(e => String(e.id) === wantedId) : null;
let how = ev ? 'id' : '';
if (!ev && wantedTitle) {
  let hits = items.filter(e => norm(e.summary) === norm(wantedTitle));
  if (!hits.length) hits = items.filter(e => norm(e.summary).includes(norm(wantedTitle)) || norm(wantedTitle).includes(norm(e.summary)));
  if (hits.length === 1) { ev = hits[0]; how = 'title'; }
  else if (hits.length > 1) return bad('AMBIGUOUS_TITLE',
    'Nothing was moved - more than one booking that date matches "' + wantedTitle + '":\n'
    + hits.map(e => '- ' + (e.summary || '(no title)') + ' ' + when(e)).join('\n')
    + '\nAsk which one they mean, then call Move Booking again with that exact title.');
}
if (!ev) return bad('NOT_ON_CALENDAR',
  'Nothing was moved - no booking on that date matches what you gave. These are the only bookings on that date:\n'
  + (items.map(e => '- ' + (e.summary || '(no title)') + ' ' + when(e)).join('\n') || '(none)'));

const desc = String(ev.description || '');
const ref = desc.match(/ref:\s*([A-Za-z0-9]+)/);
const by = desc.match(/Booked by:\s*([^|]+)/);
const title = ev.summary || '(no title)';
if (!ref) return bad('NO_REFERENCE',
  'BLOCKED - "' + title + '" carries no booker reference, so there is no way to tell whose it is. It has to be moved by hand.');
if (ref[1] !== me) return bad('NOT_YOURS',
  'BLOCKED - "' + title + '" was booked by ' + ((by && by[1].trim()) || 'someone else')
  + ', so it is not yours to move. Say exactly that and stop.');

return [{ json: { verdict:'CLEAR', matched_on: how, original_id: ev.id, title,
  description: desc, location: ev.location || '',
  attendees: (ev.attendees || []).filter(a => a.resource).map(a => ({ email: a.email })),
  old_start: (ev.start && (ev.start.dateTime || ev.start.date)) || '',
  new_start: REQ.new_start_iso, new_end: REQ.new_end_iso } }];

// The new window has to be free for the same rooms - excluding the booking
// being moved, which would otherwise collide with itself.
const R = $('Resolve Booking').first().json;
const raw = $input.first().json || {};
const items = Array.isArray(raw.items) ? raw.items.filter(e => e.status !== 'cancelled') : [];
const mine = R.attendees.map(a => String(a.email).toLowerCase());
const loc = String(R.location || '').toLowerCase();
const ns = new Date(R.new_start).getTime(), ne = new Date(R.new_end).getTime();

const clashes = [];
for (const e of items) {
  if (String(e.id) === String(R.original_id)) continue;
  const s = new Date((e.start && (e.start.dateTime || e.start.date))).getTime();
  const t = new Date((e.end && (e.end.dateTime || e.end.date))).getTime();
  if (!(s < ne && t > ns)) continue;
  const emails = (e.attendees || []).map(a => String(a.email || '').toLowerCase());
  const sameRoom = mine.some(m => emails.indexOf(m) !== -1)
    || (loc && String(e.location || '').toLowerCase() === loc);
  if (sameRoom) clashes.push(e.summary || '(no title)');
}
if (clashes.length) {
  return [{ json: { verdict:'REJECTED', reason:'ROOM_OCCUPIED',
    human: 'Nothing was moved - that room is taken in the new window by "' + clashes.join('", "')
         + '". The original booking is untouched. Tell the requester and offer another time.' } }];
}
return [{ json: Object.assign({}, R, { verdict:'CLEAR' }) }];

const R = $('Resolve Booking').first().json;
const created = $('Create Replacement').first().json || {};
return [{ json: { status:'MOVED', event_id: created.id || '', title: R.title,
  from: R.old_start, to: R.new_start,
  human: 'Moved "' + R.title + '" to the new time. Tell the requester the new date and time.' } }];

// The replacement exists but the original could not be removed, so the room is
// now double-booked. Say so plainly - this is the one outcome nobody should
// discover from the calendar a week later.
const R = $('Resolve Booking').first().json;
const created = $('Create Replacement').first().json || {};
return [{ json: { status:'PARTIAL', reason:'ORIGINAL_NOT_REMOVED', event_id: created.id || '',
  human: 'The booking was created at the new time, but the original at ' + R.old_start + ' could NOT be '
       + 'removed, so "' + R.title + '" is now on the calendar twice. Tell the requester exactly that and '
       + 'say the old one has to be deleted by hand.' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was moved and the reason is unclear. Tell the requester it did not go through.' } }];
